def average(nums: list[float]) -> float:
    # BUG: missing empty guard; wrong formula
    return sum(nums) / (len(nums) - 1)

from stats import average


def test_empty():
    assert average([]) == 0.0


def test_simple():
    assert average([1, 2, 3]) == 2.0


def test_float():
    assert abs(average([1.0, 2.0]) - 1.5) < 1e-9
